}

function runningTotals(numbers) {
  const totals = []
  for (let i = 0; i < numbers.length; i++) {
    let sumSoFar = 0
    for (let j = 0; j <= i; j++) {
      sumSoFar = sumSoFar + numbers[j]
    }
    totals.push(sumSoFar)
  }
  return totals
}

