function findMax(nums) {
  if (nums.length === 0) return null

  let max = nums[0]
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > max) max = nums[i]
  }
  return max
}

function containsDuplicate(nums) {
  const seen = new Set()
  for (let i = 0; i < nums.length; i++) {
    if (seen.has(nums[i])) return true
    seen.add(nums[i])
  }
  return false
}

